#[verus::spec]
fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // Requires clause to ensure the input is non-empty
    requires(!a.is_empty());

    // Initialize the output vector
    let mut output: Vec<Vec<String>> = Vec::with_capacity(a.len());

    // Iterate over each string in the input vector
    for s in a {
        // Split the string into lines
        let mut lines: Vec<String> = Vec::new();
        let mut current_line = String::new();
        let mut chars = s.chars().peekable();

        while let Some(c) = chars.next() {
            if c == '\n' {
                // If keepends is true, include the newline character
                if keepends {
                    current_line.push(c);
                }
                // Push the current line to lines and reset it
                lines.push(current_line);
                current_line = String::new();
            } else {
                current_line.push(c);
            }
        }

        // Push the last line if it's not empty
        if !current_line.is_empty() {
            lines.push(current_line);
        }

        // Ensure that the inner list is non-empty
        assert!(!lines.is_empty());

        // Push the lines into the output vector
        output.push(lines);
    }

    // Ensures clause to guarantee the output length matches the input length
    ensures(|output: &Vec<Vec<String>>| output.len() == a.len());

    // Ensures clause to guarantee that each inner list is non-empty
    ensures(|output: &Vec<Vec<String>>| {
        forall(|i: usize| {
            (i < output.len()).implies(!output[i].is_empty())
        })
    });

    // Return the output vector
    output
}